using System.Text;using Agro360.Application.Contracts;using Agro360.Domain.Production;using Agro360.Infrastructure.Persistence;using Agro360.Multitenancy;using Agro360.SharedKernel;using Dapper;using Microsoft.Extensions.Logging;
namespace Agro360.Infrastructure.Services;
public sealed class IndustrialProductionService(DatabaseExecutor db,ITenantContext tenant,ILogger<IndustrialProductionService> log):IIndustrialProductionService
{
 public Task<dynamic> DashboardAsync(CancellationToken ct)=>One("select count(*) filter(where status='IN_PRODUCTION') in_production,count(*) filter(where status='BLOCKED') blocked,count(*) filter(where planned_at<now() and status not in('COMPLETED','CLOSED','CANCELLED')) delayed,coalesce(sum(planned_quantity),0) planned,coalesce(sum(produced_quantity),0) produced,coalesce(avg(nullif(real_yield,0)),0) yield,(select count(*) from agro360.production_quality_checks where tenant_id=@TenantId and status='PENDING') quality_pending,(select count(*) from agro360.production_step_records where tenant_id=@TenantId and critical and conformity_status<>'CONFORMING') critical_pending,(select coalesce(sum(quantity),0) from agro360.production_losses where tenant_id=@TenantId) losses,(select coalesce(sum(duration_minutes),0) from agro360.production_stoppages where tenant_id=@TenantId and started_at>=date_trunc('month',now())) stoppage_minutes,(select coalesce(sum(real_cost),0) from agro360.production_costs where tenant_id=@TenantId) real_cost from agro360.production_orders where tenant_id=@TenantId and deleted_at is null",ct);
 public Task<IReadOnlyList<dynamic>> LookupsAsync(string type,CancellationToken ct){var sql=type switch{"plants"=>"select id,name label from agro360.production_industrial_plants where tenant_id=@TenantId and active","lines"=>"select id,name label from agro360.production_lines where tenant_id=@TenantId and active","centers"=>"select id,name label from agro360.production_work_centers where tenant_id=@TenantId and active","shifts"=>"select id,name label from agro360.production_shifts where tenant_id=@TenantId and active","products"=>"select id,name label from agro360.production_products where tenant_id=@TenantId and active","materials"=>"select id,name label from agro360.production_products where tenant_id=@TenantId and active and product_type in('RAW_MATERIAL','SEMI_FINISHED','PACKAGING')","recipes"=>"select v.id,r.name||' · v'||v.version label from agro360.production_recipe_versions v join agro360.production_recipes r on r.tenant_id=v.tenant_id and r.id=v.recipe_id where v.tenant_id=@TenantId and v.status='APPROVED' and r.active","steps"=>"select id,name label from agro360.production_steps where tenant_id=@TenantId and active","operators"=>"select id,name label from agro360.identity_users where tenant_id=@TenantId and status='ACTIVE' and deleted_at is null",_=>throw new DomainException("Consulta auxiliar inválida.","agro360.production_lookup_invalid")};return List(sql,ct);}
 public Task<IReadOnlyList<dynamic>> RecipesAsync(ProductionQuery q,CancellationToken ct)=>Paged("select r.id,r.code,r.name,p.name product_name,r.active,v.id version_id,v.version,v.status,v.expected_yield,v.valid_until from agro360.production_recipes r join agro360.production_products p on p.tenant_id=r.tenant_id and p.id=r.finished_product_id left join lateral(select * from agro360.production_recipe_versions x where x.tenant_id=r.tenant_id and x.recipe_id=r.id order by version desc limit 1)v on true where r.tenant_id=@TenantId and r.deleted_at is null and (@Search is null or r.name ilike '%'||@Search||'%' or r.code ilike '%'||@Search||'%') and (@Status is null or v.status=@Status) order by r.name",q,ct);
 public Task<Guid> CreateRecipeAsync(RecipeCommand x,CancellationToken ct)=>SaveRecipe(null,x,ct);
 public Task<Guid> VersionRecipeAsync(Guid recipeId,RecipeCommand x,CancellationToken ct)=>SaveRecipe(recipeId,x,ct);
 private Task<Guid> SaveRecipe(Guid? recipeId,RecipeCommand x,CancellationToken ct){IndustrialProductionRules.Recipe(x.BaseQuantity,x.ExpectedYield,x.Items.Select(i=>(i.MaterialId,i.Quantity,i.Unit)));return Tx(async(c,t)=>{var id=recipeId??Guid.CreateVersion7();if(recipeId is null)await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_recipes(id,tenant_id,code,name,finished_product_id,active,created_by,updated_by) values(@Id,@TenantId,@Code,@Name,@Product,true,@UserId,@UserId)",new{Id=id,tenant.TenantId,x.Code,x.Name,Product=x.FinishedProductId,tenant.UserId},t,cancellationToken:ct));else if(!await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.production_recipes where tenant_id=@TenantId and id=@Id and active and deleted_at is null)",new{tenant.TenantId,Id=id},t,cancellationToken:ct)))throw new NotFoundException("Formulação",id);var ver=await c.ExecuteScalarAsync<int>(new CommandDefinition("select coalesce(max(version),0)+1 from agro360.production_recipe_versions where tenant_id=@TenantId and recipe_id=@Id",new{tenant.TenantId,Id=id},t,cancellationToken:ct));var vid=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_recipe_versions(id,tenant_id,recipe_id,version,base_quantity,unit,expected_yield,expected_loss,instructions,status,technical_responsible_id,valid_from,valid_until,created_by,updated_by) values(@Id,@TenantId,@Recipe,@Version,@BaseQuantity,@Unit,@ExpectedYield,@ExpectedLoss,@Instructions,'DRAFT',@TechnicalResponsibleId,@ValidFrom,@ValidUntil,@UserId,@UserId)",new{Id=vid,tenant.TenantId,Recipe=id,Version=ver,x.BaseQuantity,x.Unit,x.ExpectedYield,x.ExpectedLoss,x.Instructions,x.TechnicalResponsibleId,x.ValidFrom,x.ValidUntil,tenant.UserId},t,cancellationToken:ct));foreach(var i in x.Items)await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_recipe_items(id,tenant_id,recipe_version_id,material_id,quantity,unit,loss_percent,created_by,updated_by) values(gen_random_uuid(),@TenantId,@Version,@MaterialId,@Quantity,@Unit,@LossPercent,@UserId,@UserId)",new{tenant.TenantId,Version=vid,i.MaterialId,i.Quantity,i.Unit,i.LossPercent,tenant.UserId},t,cancellationToken:ct));return vid;});}
 public Task ApproveRecipeAsync(Guid id,CancellationToken ct)=>Tx(async(c,t)=>{var n=await c.ExecuteAsync(new CommandDefinition("update agro360.production_recipe_versions set status='APPROVED',approved_at=now(),approved_by=@UserId,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id and status='DRAFT'",new{tenant.TenantId,tenant.UserId,Id=id},t,cancellationToken:ct));if(n==0)throw new ConflictException("Somente versão em rascunho pode ser aprovada; versão aprovada é imutável.");});
 public Task<IReadOnlyList<dynamic>> OrdersAsync(ProductionQuery q,CancellationToken ct)=>Paged("select o.*,p.name product_name,l.name line_name from agro360.production_orders o join agro360.production_products p on p.tenant_id=o.tenant_id and p.id=o.finished_product_id join agro360.production_lines l on l.tenant_id=o.tenant_id and l.id=o.line_id where o.tenant_id=@TenantId and o.deleted_at is null and (@Search is null or o.number ilike '%'||@Search||'%' or o.planned_batch ilike '%'||@Search||'%') and (@Status is null or o.status=@Status) and (@LineId is null or o.line_id=@LineId) order by o.planned_at desc",q,ct);
 public Task<dynamic> OrderAsync(Guid id,CancellationToken ct)=>One("select o.*,p.name product_name,l.name line_name,(select jsonb_agg(e order by e.created_at) from agro360.production_order_events e where e.tenant_id=o.tenant_id and e.order_id=o.id) history from agro360.production_orders o join agro360.production_products p on p.tenant_id=o.tenant_id and p.id=o.finished_product_id join agro360.production_lines l on l.tenant_id=o.tenant_id and l.id=o.line_id where o.tenant_id=@TenantId and o.id=@Id",ct,new{Id=id});
 public Task<Guid> CreateOrderAsync(ProductionOrderCommand x,CancellationToken ct){IndustrialProductionRules.Order(x.FinishedProductId,x.RecipeVersionId,x.PlannedQuantity,x.Unit);return Tx(async(c,t)=>{if(!await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.production_recipe_versions v join agro360.production_recipes r on r.tenant_id=v.tenant_id and r.id=v.recipe_id where v.tenant_id=@TenantId and v.id=@Id and v.status='APPROVED' and r.active)",new{tenant.TenantId,Id=x.RecipeVersionId},t,cancellationToken:ct)))throw new DomainException("Formulação deve estar ativa e aprovada.","agro360.production_recipe_unavailable");var id=Guid.CreateVersion7();var number=$"OP-{DateTime.UtcNow:yyyy}-{await c.ExecuteScalarAsync<long>(new CommandDefinition("select nextval('agro360.production_order_number_seq')",transaction:t,cancellationToken:ct)):000000}";await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_orders(id,tenant_id,number,plant_id,line_id,finished_product_id,recipe_version_id,planned_batch,planned_quantity,unit,planned_at,priority,responsible_id,demand_origin,sales_order_id,requires_reservation,status,notes,created_by,updated_by) values(@Id,@TenantId,@Number,@PlantId,@LineId,@FinishedProductId,@RecipeVersionId,@PlannedBatch,@PlannedQuantity,@Unit,@PlannedAt,@Priority,@ResponsibleId,@DemandOrigin,@SalesOrderId,@RequiresReservation,'PLANNED',@Notes,@UserId,@UserId);insert into agro360.production_order_events(id,tenant_id,order_id,from_status,to_status,reason,created_by,updated_by) values(gen_random_uuid(),@TenantId,@Id,null,'PLANNED','Ordem criada',@UserId,@UserId)",new{Id=id,tenant.TenantId,Number=number,x.PlantId,x.LineId,x.FinishedProductId,x.RecipeVersionId,x.PlannedBatch,x.PlannedQuantity,x.Unit,x.PlannedAt,x.Priority,x.ResponsibleId,x.DemandOrigin,x.SalesOrderId,x.RequiresReservation,x.Notes,tenant.UserId},t,cancellationToken:ct));return id;});}
 public Task ChangeStatusAsync(Guid id,string status,string? reason,CancellationToken ct)=>Tx(async(c,t)=>{var o=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select status,requires_reservation,stock_reserved,exists(select 1 from agro360.production_recipe_items i where i.tenant_id=o.tenant_id and i.recipe_version_id=o.recipe_version_id) has_items,exists(select 1 from agro360.production_step_records r where r.tenant_id=o.tenant_id and r.order_id=o.id and r.status='COMPLETED') has_record,not exists(select 1 from agro360.production_step_records r where r.tenant_id=o.tenant_id and r.order_id=o.id and r.critical and r.conformity_status<>'CONFORMING') critical_complete,not exists(select 1 from agro360.production_quality_checks q where q.tenant_id=o.tenant_id and q.order_id=o.id and q.mandatory and q.status<>'APPROVED') quality_approved from agro360.production_orders o where tenant_id=@TenantId and id=@Id for update",new{tenant.TenantId,Id=id},t,cancellationToken:ct))??throw new NotFoundException("Ordem",id);IndustrialProductionRules.Transition((string)o.status,status.ToUpperInvariant(),reason,(bool)o.has_items,(bool)o.has_record,(bool)o.stock_reserved,(bool)o.requires_reservation,(bool)o.critical_complete,(bool)o.quality_approved);await c.ExecuteAsync(new CommandDefinition("update agro360.production_orders set status=@Status,cancel_reason=case when @Status='CANCELLED' then @Reason end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id;insert into agro360.production_order_events(id,tenant_id,order_id,from_status,to_status,reason,created_by,updated_by) values(gen_random_uuid(),@TenantId,@Id,@From,@Status,@Reason,@UserId,@UserId)",new{tenant.TenantId,tenant.UserId,Id=id,From=(string)o.status,Status=status.ToUpperInvariant(),Reason=reason},t,cancellationToken:ct));log.LogInformation("Ordem {OrderId} mudou de {From} para {To}",id,(string)o.status,status);});
 public Task<Guid> RecordAsync(ProductionRecordCommand x,CancellationToken ct){IndustrialProductionRules.Record(x.OperatorId,x.Produced,x.Consumed,x.Loss,x.LossReason);if(x.EndedAt<x.StartedAt)throw new DomainException("Fim deve ser posterior ao início.","agro360.production_period_invalid");return Tx(async(c,t)=>{var id=Guid.CreateVersion7();var critical=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select critical from agro360.production_steps where tenant_id=@TenantId and id=@Step",new{tenant.TenantId,Step=x.StepId},t,cancellationToken:ct));if(critical&&x.Temperature is null)throw new DomainException("Etapa crítica exige temperatura.","agro360.production_temperature_required");await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_step_records(id,tenant_id,order_id,step_id,operator_id,line_id,started_at,ended_at,produced_quantity,consumed_quantity,loss_quantity,scrap_quantity,loss_reason,notes,input_batch,output_batch,temperature,evidence_reference,critical,conformity_status,status,created_by,updated_by) values(@Id,@TenantId,@OrderId,@StepId,@OperatorId,@LineId,@StartedAt,@EndedAt,@Produced,@Consumed,@Loss,@Scrap,@LossReason,@Notes,@InputBatch,@OutputBatch,@Temperature,@EvidenceReference,@Critical,case when @Critical and @Temperature is null then 'NON_CONFORMING' else 'CONFORMING' end,'COMPLETED',@UserId,@UserId);update agro360.production_orders set produced_quantity=produced_quantity+@Produced,consumed_quantity=consumed_quantity+@Consumed,real_yield=case when consumed_quantity+@Consumed>0 then (produced_quantity+@Produced)/(consumed_quantity+@Consumed)*100 else 0 end,status='IN_PRODUCTION',updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@OrderId",new{Id=id,tenant.TenantId,x.OrderId,x.StepId,x.OperatorId,x.LineId,x.StartedAt,x.EndedAt,x.Produced,x.Consumed,x.Loss,x.Scrap,x.LossReason,x.Notes,x.InputBatch,x.OutputBatch,x.Temperature,x.EvidenceReference,Critical=critical,tenant.UserId},t,cancellationToken:ct));return id;});}
 public Task<Guid> ConsumeAsync(MaterialConsumptionCommand x,CancellationToken ct){if(x.Quantity<=0)throw new DomainException("Consumo deve ser positivo.","agro360.production_consumption_invalid");if(x.ExpiredOverride&&string.IsNullOrWhiteSpace(x.Justification))throw new DomainException("Lote vencido exige permissão e justificativa.","agro360.production_expired_justification_required");return Tx(async(c,t)=>{var lot=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select quantity quantity_available,expires_on,quality_status from agro360.inventory_stock_lots where tenant_id=@TenantId and id=@Id for update",new{tenant.TenantId,Id=x.StockLotId},t,cancellationToken:ct))??throw new NotFoundException("Lote de estoque",x.StockLotId);if((decimal)lot.quantity_available<x.Quantity)throw new DomainException("Consumo maior que o estoque disponível.","agro360.production_insufficient_stock");if((string)lot.quality_status=="BLOCKED")throw new DomainException("Lote bloqueado pela qualidade não pode ser consumido.","agro360.production_batch_blocked");if((DateOnly?)lot.expires_on<DateOnly.FromDateTime(DateTime.UtcNow)&&!x.ExpiredOverride)throw new DomainException("Lote vencido não pode ser consumido.","agro360.production_batch_expired");var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_material_consumptions(id,tenant_id,order_id,material_id,stock_lot_id,quantity,unit,justification,status,created_by,updated_by) values(@Id,@TenantId,@OrderId,@MaterialId,@StockLotId,@Quantity,@Unit,@Justification,'POSTED',@UserId,@UserId);update agro360.inventory_stock_lots set quantity=quantity-@Quantity where tenant_id=@TenantId and id=@StockLotId",new{Id=id,tenant.TenantId,x.OrderId,x.MaterialId,x.StockLotId,x.Quantity,x.Unit,x.Justification,tenant.UserId},t,cancellationToken:ct));return id;});}
 public Task<Guid> QualityAsync(QualityDecisionCommand x,CancellationToken ct){var result=x.Result.ToUpperInvariant();if((result is "REJECTED" or "BLOCKED")&&string.IsNullOrWhiteSpace(x.Reason))throw new DomainException("Reprovação ou bloqueio exige motivo.","agro360.production_quality_reason_required");return Tx(async(c,t)=>{var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_quality_checks(id,tenant_id,order_id,batch_id,step_id,status,reason,report_reference,evidence_reference,mandatory,decided_at,decided_by,created_by,updated_by) values(@Id,@TenantId,@OrderId,@BatchId,@StepId,@Status,@Reason,@Report,@Evidence,true,now(),@UserId,@UserId,@UserId);update agro360.production_batches set quality_status=@Status,released_at=case when @Status='APPROVED' then now() end,released_by=case when @Status='APPROVED' then @UserId end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@BatchId;update agro360.production_orders set status=case when @Status in('REJECTED','BLOCKED') then 'BLOCKED' else status end,updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@OrderId",new{Id=id,tenant.TenantId,x.OrderId,x.BatchId,x.StepId,Status=result,x.Reason,Report=x.ReportReference,Evidence=x.EvidenceReference,tenant.UserId},t,cancellationToken:ct));return id;});}
 public Task<Guid> StopAsync(StoppageCommand x,CancellationToken ct){if(string.IsNullOrWhiteSpace(x.Reason)||x.EndedAt<=x.StartedAt)throw new DomainException("Parada exige motivo e período válido.","agro360.production_stoppage_invalid");return Tx(async(c,t)=>{var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into agro360.production_stoppages(id,tenant_id,line_id,order_id,equipment_id,type,reason,critical,started_at,ended_at,duration_minutes,responsible_id,estimated_impact,corrective_action,status,created_by,updated_by) values(@Id,@TenantId,@LineId,@OrderId,@EquipmentId,@Type,@Reason,@Critical,@StartedAt,@EndedAt,@Minutes,@ResponsibleId,@EstimatedImpact,@CorrectiveAction,'COMPLETED',@UserId,@UserId)",new{Id=id,tenant.TenantId,x.LineId,x.OrderId,x.EquipmentId,x.Type,x.Reason,x.Critical,x.StartedAt,x.EndedAt,Minutes=(int)(x.EndedAt-x.StartedAt).TotalMinutes,x.ResponsibleId,x.EstimatedImpact,x.CorrectiveAction,tenant.UserId},t,cancellationToken:ct));return id;});}
 public Task<IReadOnlyList<dynamic>> TraceAsync(string batch,CancellationToken ct)=>List("select b.batch_number,b.quality_status,o.number order_number,p.name product_name,t.relation_type,t.source_batch,t.source_entity,t.source_reference,t.created_at from agro360.production_batches b join agro360.production_orders o on o.tenant_id=b.tenant_id and o.id=b.order_id join agro360.production_products p on p.tenant_id=b.tenant_id and p.id=b.product_id left join agro360.production_batch_traceability t on t.tenant_id=b.tenant_id and t.batch_id=b.id where b.tenant_id=@TenantId and b.batch_number=@Batch order by t.created_at",ct,new{Batch=batch});
 public async Task<byte[]> ExportAsync(string report,ProductionQuery q,CancellationToken ct){var rows=report switch{"orders"=>await OrdersAsync(q,ct),"recipes"=>await RecipesAsync(q,ct),_=>throw new DomainException("Relatório inválido.","agro360.production_report_invalid")};var s=new StringBuilder("sep=;\n");s.AppendLine(report=="orders"?"Número;Produto;Linha;Planejado;Produzido;Rendimento;Status":"Código;Formulação;Produto;Versão;Rendimento;Status");foreach(var r in rows)s.AppendLine(report=="orders"?$"{r.number};{r.product_name};{r.line_name};{r.planned_quantity};{r.produced_quantity};{r.real_yield};{r.status}":$"{r.code};{r.name};{r.product_name};{r.version};{r.expected_yield};{r.status}");return Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(s.ToString())).ToArray();}
 private Task<T> Tx<T>(Func<Npgsql.NpgsqlConnection,Npgsql.NpgsqlTransaction,Task<T>> f)=>db.InTenantTransactionAsync(f,CancellationToken.None);private Task Tx(Func<Npgsql.NpgsqlConnection,Npgsql.NpgsqlTransaction,Task> f)=>db.InTenantTransactionAsync(f,CancellationToken.None);
 private Task<dynamic> One(string sql,CancellationToken ct,object? extra=null)=>db.InTenantTransactionAsync<dynamic>(async(c,t)=>{var p=new DynamicParameters(extra);p.Add("TenantId",tenant.TenantId);return await c.QuerySingleOrDefaultAsync(new CommandDefinition(sql,p,t,cancellationToken:ct))??throw new NotFoundException("Produção",Guid.Empty);},ct);
 private Task<IReadOnlyList<dynamic>> List(string sql,CancellationToken ct,object? extra=null)=>db.InTenantTransactionAsync<IReadOnlyList<dynamic>>(async(c,t)=>{var p=new DynamicParameters(extra);p.Add("TenantId",tenant.TenantId);return(await c.QueryAsync(new CommandDefinition(sql,p,t,cancellationToken:ct))).AsList();},ct);
 private Task<IReadOnlyList<dynamic>> Paged(string sql,ProductionQuery q,CancellationToken ct)=>db.InTenantTransactionAsync<IReadOnlyList<dynamic>>(async(c,t)=>(await c.QueryAsync(new CommandDefinition(sql+" limit @Take offset @Skip",new{tenant.TenantId,Search=string.IsNullOrWhiteSpace(q.Search)?null:q.Search,Status=string.IsNullOrWhiteSpace(q.Status)?null:q.Status,q.LineId,Take=Math.Clamp(q.PageSize,1,100),Skip=(Math.Max(1,q.Page)-1)*Math.Clamp(q.PageSize,1,100)},t,cancellationToken:ct))).AsList(),ct);
}
